 d=sum((line['debit'] for line in e['lines']),D(0)); c=sum((line['credit'] for line in e['lines']),D(0))
 assert d==c,(e['ref'],d,c)
 for line in e['lines']:
  accounts[line['account']]+=line['debit']-line['credit']
assert sum(accounts.values())==0
out={'accounts':{k:{'debit':float(max(v,D('0'))),'credit':float(max(-v,D('0')))} for k,v in accounts.items()}}
